<?php
declare(strict_types=1); require_once __DIR__.'/admin-layout.php'; require_once __DIR__.'/../models/Driver.php'; require_once __DIR__.'/../models/Vehicle.php';
$m=new Driver();$vm=new Vehicle();$flash=getFlashMessage();$message=$flash['message']??'';$type=$flash['type']??'success';$editing=null;
if($_SERVER['REQUEST_METHOD']==='POST'){try{if(!verifyAdminCsrf())throw new RuntimeException('Security token expired. Refresh the page.');$a=$_POST['action']??'';$id=(int)($_POST['id']??0);if($a==='save'){$name=trim($_POST['full_name']??'');$mobile=preg_replace('/\D+/','',$_POST['mobile_number']??'');$status=$_POST['status']??'AVAILABLE';if($name===''||strlen($mobile)<10)throw new RuntimeException('Driver name and a valid mobile number are required.');if(!in_array($status,['AVAILABLE','ASSIGNED','OFF_DUTY','INACTIVE'],true))throw new RuntimeException('Invalid status.');$d=['full_name'=>$name,'mobile_number'=>$mobile,'email'=>trim($_POST['email']??''),'license_number'=>trim($_POST['license_number']??''),'vehicle_id'=>((int)($_POST['vehicle_id']??0))?:null,'status'=>$status,'notes'=>trim($_POST['notes']??'')];if($id)$m->update($id,$d);else$m->create($d);$success=$id?'Driver updated successfully.':'Driver added successfully.';setFlashMessage($success);header('Location: drivers.php');exit;}elseif($a==='delete'){if($id<1)throw new RuntimeException('Invalid driver.');$m->delete($id);setFlashMessage('Driver deleted successfully.');header('Location: drivers.php');exit;}}catch(Throwable $e){$message=$e->getMessage();$type='danger';}}
if(isset($_GET['edit']))$editing=$m->find((int)$_GET['edit']);$rows=$m->all(trim($_GET['search']??''),strtoupper(trim($_GET['status']??'')));$vehicles=$vm->all();$csrf=adminCsrfToken();adminHeader('Drivers','Manage drivers and their default vehicle assignment.');
?><div class="admin-card mb-4"><div class="admin-card-head"><div><h2><?= $editing?'Edit Driver':'Add Driver' ?></h2><p>Driver records are used when assigning resources to confirmed bookings.</p></div><?php if($editing):?><a class="btn-admin btn-light" href="drivers.php">Cancel</a><?php endif;?></div><?php if($message):?><div class="px-4 pt-3"><div class="alert alert-<?=$type?> border-0 mb-0"><?=e($message)?></div></div><?php endif;?><form method="post" class="row g-3 p-4"><input type="hidden" name="csrf_token" value="<?=e($csrf)?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?= (int)($editing['id']??0)?>"><div class="col-md-5"><label class="form-label">Full Name *</label><input class="form-control" name="full_name" required value="<?=e($editing['full_name']??'')?>"></div><div class="col-md-3"><label class="form-label">Mobile *</label><input class="form-control" name="mobile_number" required value="<?=e($editing['mobile_number']??'')?>"></div><div class="col-md-4"><label class="form-label">Email</label><input class="form-control" type="email" name="email" value="<?=e($editing['email']??'')?>"></div><div class="col-md-4"><label class="form-label">License Number</label><input class="form-control" name="license_number" value="<?=e($editing['license_number']??'')?>"></div><div class="col-md-4"><label class="form-label">Default Vehicle</label><select class="form-select" name="vehicle_id"><option value="0">Not assigned</option><?php foreach($vehicles as $v):?><option value="<?=(int)$v['id']?>" <?=((int)($editing['vehicle_id']??0)===(int)$v['id'])?'selected':''?>><?=e($v['vehicle_name'])?><?= $v['registration_number']?' — '.e($v['registration_number']):''?></option><?php endforeach;?></select></div><div class="col-md-4"><label class="form-label">Status</label><select class="form-select" name="status"><?php foreach(['AVAILABLE','ASSIGNED','OFF_DUTY','INACTIVE'] as $s):?><option value="<?=$s?>" <?=($editing['status']??'AVAILABLE')===$s?'selected':''?>><?=e(str_replace('_',' ',$s))?></option><?php endforeach;?></select></div><div class="col-12"><label class="form-label">Notes</label><textarea class="form-control" name="notes" rows="3"><?=e($editing['notes']??'')?></textarea></div><div class="col-12"><button class="btn-admin btn-primary"><i class="ri-save-line"></i> <?=$editing?'Update Driver':'Add Driver'?></button></div></form></div>
<div class="admin-card"><div class="admin-card-head"><div><h2>Drivers</h2><p><?=count($rows)?> driver(s)</p></div><form class="toolbar" method="get"><input class="form-control" name="search" placeholder="Search name, mobile or license" value="<?=e($_GET['search']??'')?>"><select class="form-select" name="status"><option value="">All</option><?php foreach(['AVAILABLE','ASSIGNED','OFF_DUTY','INACTIVE'] as $s):?><option value="<?=$s?>" <?=($_GET['status']??'')===$s?'selected':''?>><?=e(str_replace('_',' ',$s))?></option><?php endforeach;?></select><button class="btn-admin btn-primary">Search</button></form></div><div class="table-responsive"><table class="table admin-table align-middle mb-0"><thead><tr><th>Driver</th><th>Mobile</th><th>License</th><th>Vehicle</th><th>Status</th><th class="text-end">Actions</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><strong><?=e($r['full_name'])?></strong><div class="small text-muted"><?=e($r['email']??'')?></div></td><td><?=e($r['mobile_number'])?></td><td><?=e($r['license_number']??'—')?></td><td><?=e($r['vehicle_name']??'Not assigned')?></td><td><span class="status-pill status-<?=strtolower($r['status'])?>"><?=e(str_replace('_',' ',$r['status']))?></span></td><td class="text-end"><a class="btn-admin btn-light btn-sm" href="drivers.php?edit=<?=(int)$r['id']?>">Edit</a><form class="d-inline" method="post" onsubmit="return confirm('Delete this driver?')"><input type="hidden" name="csrf_token" value="<?=e($csrf)?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=(int)$r['id']?>"><button class="btn-admin btn-danger-soft btn-sm">Delete</button></form></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="6" class="text-center py-5 text-muted">No drivers found.</td></tr><?php endif;?></tbody></table></div></div><?php adminFooter();
